<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kanban Board</title>
  <style>
    :root {
      color-scheme: light;
      --background: #f3f5f9;
      --surface: #ffffff;
      --text: #172033;
      --muted: #687086;
      --border: #e2e6ee;
      --accent: #5b67e8;
      --danger: #dc3545;
      --shadow: 0 8px 24px rgba(31, 42, 68, 0.08);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      background: var(--background);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    main {
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
      padding: 40px 0;
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 28px;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.7rem, 3vw, 2.35rem);
      letter-spacing: -0.04em;
    }

    .new-card-form {
      display: flex;
      gap: 10px;
      width: min(100%, 440px);
    }

    #new-card {
      flex: 1;
      min-width: 0;
      padding: 12px 14px;
      border: 1px solid var(--border);
      border-radius: 10px;
      background: var(--surface);
      color: var(--text);
      font: inherit;
      outline: none;
      box-shadow: 0 2px 8px rgba(31, 42, 68, 0.04);
    }

    #new-card:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(91, 103, 232, 0.14);
    }

    #add-card {
      padding: 12px 18px;
      border: 0;
      border-radius: 10px;
      background: var(--accent);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 6px 14px rgba(91, 103, 232, 0.24);
    }

    #add-card:hover {
      background: #4d58d7;
    }

    #add-card:active {
      transform: translateY(1px);
    }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
      align-items: start;
    }

    .column {
      min-height: 390px;
      padding: 16px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: rgba(255, 255, 255, 0.68);
      transition: border-color 150ms ease, background 150ms ease;
    }

    .column.drag-over {
      border-color: var(--accent);
      background: rgba(91, 103, 232, 0.08);
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 14px;
    }

    .column-header h2 {
      margin: 0;
      font-size: 1rem;
      letter-spacing: 0.01em;
    }

    .count {
      display: inline-grid;
      min-width: 27px;
      height: 27px;
      place-items: center;
      padding: 0 8px;
      border-radius: 999px;
      background: #e9ecf4;
      color: var(--muted);
      font-size: 0.82rem;
      font-weight: 800;
    }

    .card-container {
      min-height: 315px;
      display: flex;
      flex-direction: column;
      gap: 11px;
    }

    .card {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      padding: 15px;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: var(--surface);
      box-shadow: var(--shadow);
      cursor: grab;
      line-height: 1.4;
      overflow-wrap: anywhere;
    }

    .card:active {
      cursor: grabbing;
    }

    .card.dragging {
      opacity: 0.45;
    }

    .card-title {
      flex: 1;
      padding-top: 2px;
    }

    .card-del {
      flex: 0 0 auto;
      width: 28px;
      height: 28px;
      border: 0;
      border-radius: 8px;
      background: #fff0f1;
      color: var(--danger);
      font-size: 1.2rem;
      line-height: 1;
      cursor: pointer;
    }

    .card-del:hover {
      background: #ffdfe2;
    }

    @media (max-width: 760px) {
      main {
        padding-top: 24px;
      }

      .topbar {
        align-items: stretch;
        flex-direction: column;
      }

      .new-card-form {
        width: 100%;
      }

      .board {
        grid-template-columns: 1fr;
      }

      .column {
        min-height: 220px;
      }

      .card-container {
        min-height: 145px;
      }
    }
  </style>
</head>
<body>
  <main>
    <div class="topbar">
      <h1>Kanban Board</h1>
      <form class="new-card-form" id="new-card-form">
        <input id="new-card" type="text" placeholder="Add a new task…" autocomplete="off" aria-label="New card title">
        <button id="add-card" type="submit">Add card</button>
      </form>
    </div>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo">
        <header class="column-header">
          <h2>To Do</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container"></div>
      </section>

      <section class="column" id="col-doing">
        <header class="column-header">
          <h2>Doing</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container"></div>
      </section>

      <section class="column" id="col-done">
        <header class="column-header">
          <h2>Done</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container"></div>
      </section>
    </section>
  </main>

  <script>
    (() => {
      const STORAGE_KEY = "kanban-board-state";
      const columnIds = ["col-todo", "col-doing", "col-done"];
      const form = document.getElementById("new-card-form");
      const input = document.getElementById("new-card");
      let draggedCard = null;

      function makeId() {
        return "card-" + Date.now().toString(36) + "-" +
          Math.random().toString(36).slice(2, 9);
      }

      function createCard(title, id = makeId()) {
        const card = document.createElement("article");
        card.className = "card";
        card.id = id;
        card.draggable = true;

        const titleElement = document.createElement("span");
        titleElement.className = "card-title";
        titleElement.textContent = title;

        const deleteButton = document.createElement("button");
        deleteButton.className = "card-del";
        deleteButton.type = "button";
        deleteButton.textContent = "×";
        deleteButton.setAttribute("aria-label", `Delete ${title}`);

        deleteButton.addEventListener("click", () => {
          card.remove();
          updateCounts();
          saveBoard();
        });

        card.addEventListener("dragstart", event => {
          draggedCard = card;
          card.classList.add("dragging");
          event.dataTransfer.effectAllowed = "move";
          event.dataTransfer.setData("text/plain", card.id);
        });

        card.addEventListener("dragend", () => {
          card.classList.remove("dragging");
          document.querySelectorAll(".column").forEach(column => {
            column.classList.remove("drag-over");
          });
          draggedCard = null;
        });

        card.append(titleElement, deleteButton);
        return card;
      }

      function updateCounts() {
        columnIds.forEach(columnId => {
          const column = document.getElementById(columnId);
          const count = column.querySelectorAll(".card").length;
          const countElement = column.querySelector(".count");
          countElement.textContent = count;
          countElement.setAttribute(
            "aria-label",
            `${count} card${count === 1 ? "" : "s"}`
          );
        });
      }

      function saveBoard() {
        const state = {};

        columnIds.forEach(columnId => {
          state[columnId] = Array.from(
            document.querySelectorAll(`#${columnId} .card`)
          ).map(card => ({
            id: card.id,
            title: card.querySelector(".card-title").textContent
          }));
        });

        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      }

      function restoreBoard() {
        let state;

        try {
          state = JSON.parse(localStorage.getItem(STORAGE_KEY));
        } catch {
          state = null;
        }

        if (!state || typeof state !== "object") {
          updateCounts();
          return;
        }

        columnIds.forEach(columnId => {
          const container = document.querySelector(
            `#${columnId} .card-container`
          );
          const cards = Array.isArray(state[columnId]) ? state[columnId] : [];

          cards.forEach(savedCard => {
            if (
              savedCard &&
              typeof savedCard.title === "string" &&
              savedCard.title.trim()
            ) {
              container.appendChild(
                createCard(savedCard.title, savedCard.id || makeId())
              );
            }
          });
        });

        updateCounts();
      }

      form.addEventListener("submit", event => {
        event.preventDefault();
        const title = input.value.trim();

        if (!title) return;

        document.querySelector("#col-todo .card-container")
          .appendChild(createCard(title));

        input.value = "";
        input.focus();
        updateCounts();
        saveBoard();
      });

      document.querySelectorAll(".column").forEach(column => {
        column.addEventListener("dragover", event => {
          event.preventDefault();
          event.dataTransfer.dropEffect = "move";
          column.classList.add("drag-over");
        });

        column.addEventListener("dragleave", event => {
          if (!column.contains(event.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });

        column.addEventListener("drop", event => {
          event.preventDefault();
          column.classList.remove("drag-over");

          const cardId = event.dataTransfer.getData("text/plain");
          const card = draggedCard || document.getElementById(cardId);

          if (card && card.classList.contains("card")) {
            column.querySelector(".card-container").appendChild(card);
            updateCounts();
            saveBoard();
          }
        });
      });

      restoreBoard();
    })();
  </script>
</body>
</html>
